"""Algorithm: exact representation counting in a certified box."""

from __future__ import annotations

from math import isqrt
from typing import List, Tuple

Form = Tuple[int, int, int]   # a x^2 + b x y + c y^2


def discriminant(form: Form) -> int:
    a, b, c = form
    return b * b - 4 * a * c


def certified_bounds(form: Form, n: int) -> Tuple[int, int]:
    """Return (y_max, t_max) with |y| <= y_max and |2ax+by| <= t_max for every
    integer solution of form(x,y) = n.  Derived from the identity
    4a * form(x,y) = (2ax + by)^2 + |D| y^2 with D < 0."""
    a, b, c = form
    absd = -discriminant(form)
    if absd <= 0:
        raise ValueError("form must have negative discriminant")
    return isqrt(4 * a * n // absd), isqrt(4 * a * n)


def representations(form: Form, n: int) -> List[Tuple[int, int]]:
    """All integer solutions of form(x,y) = n, for n > 0 and disc(form) < 0.

    The enumeration is provably exhaustive, so len(...) is the exact
    representation number r_form(n).  Complexity: O(sqrt(a n / |D|)) integer
    operations, each dominated by one integer square root.
    """
    a, b, _ = form
    absd = -discriminant(form)
    if n <= 0:
        return []
    y_max, _ = certified_bounds(form, n)
    out: List[Tuple[int, int]] = []
    for y in range(-y_max, y_max + 1):
        rest = 4 * a * n - absd * y * y
        if rest < 0:
            continue
        t = isqrt(rest)
        if t * t != rest:
            continue
        for signed_t in ({t, -t} if t else {0}):
            num = signed_t - b * y
            if num % (2 * a) == 0:
                out.append((num // (2 * a), y))
    return sorted(set(out))


def representation_vector(forms: List[Form], n: int) -> Tuple[int, ...]:
    """r_D(n) over a list of reduced forms of the same discriminant."""
    return tuple(len(representations(f, n)) for f in forms)


if __name__ == "__main__":
    P: Form = (1, 0, 5)          # x^2 + 5y^2
    Q: Form = (2, 2, 3)          # 2x^2 + 2xy + 3y^2
    for n in (21, 87, 1189):
        print(n, representation_vector([P, Q], n))

