function DIAL_TABLE(D):
    m <- |D|
    F <- REDUCED_FORMS(D)                       # |b| <= a <= c, a <= sqrt(m/3)
    for each form f in F:
        S[f] <- { f(x,y) mod m : x,y in Z/m } intersect (Z/m)^*
    return S

function IS_RESIDUE_DIAL(D):
    S <- DIAL_TABLE(D)
    for all pairs f != g in domain(S):
        if S[f] intersect S[g] nonempty: return FALSE
    return TRUE                                  # <=> one class per genus

function READ_CLASS(D, N):                       # requires IS_RESIDUE_DIAL(D)
    r <- N mod |D|
    return the unique index i with r in S[f_i], or NONE

