"""Algorithm: build the dial table of a discriminant and decide readability."""

from __future__ import annotations

from itertools import product
from math import isqrt
from typing import Dict, List, Optional, Set, Tuple

Form = Tuple[int, int, int]


def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return abs(a)


def reduced_forms(disc: int) -> List[Form]:
    """Reduced primitive positive definite forms of discriminant disc < 0.

    Reduction forces |b| <= a <= c, hence a <= sqrt(|disc|/3); the loop is
    O(|disc|) and returns the h(disc) class representatives.
    """
    if disc >= 0 or disc % 4 not in (0, 1):
        raise ValueError("disc must be a negative discriminant")
    forms: List[Form] = []
    for a in range(1, isqrt(abs(disc) // 3) + 2):
        for b in range(-a, a + 1):
            num = b * b - disc
            if num % (4 * a):
                continue
            c = num // (4 * a)
            if c < a or ((abs(b) == a or a == c) and b < 0):
                continue
            if gcd(gcd(a, b), c) != 1:
                continue
            forms.append((a, b, c))
    return forms


def unit_value_set(form: Form, m: int) -> Set[int]:
    """The residues mod m attained by `form` that are invertible mod m.

    Complexity O(m^2) modular operations; this is the finite check that
    establishes soundness of the dial.
    """
    a, b, c = form
    units = {u for u in range(m) if gcd(u, m) == 1}
    values = {(a * x * x + b * x * y + c * y * y) % m for x, y in product(range(m), repeat=2)}
    return values & units


def dial_table(disc: int) -> Dict[Form, Set[int]]:
    """Map every reduced form of discriminant disc to its admissible residues."""
    m = abs(disc)
    return {f: unit_value_set(f, m) for f in reduced_forms(disc)}


def is_residue_dial(disc: int) -> bool:
    """True iff the admissible-residue sets are pairwise disjoint, i.e. iff the
    representation vector is a function of N mod |disc| (one class per genus)."""
    sets = list(dial_table(disc).values())
    return all(not (sets[i] & sets[j]) for i in range(len(sets)) for j in range(i + 1, len(sets)))


def readout(disc: int) -> Dict[int, int]:
    """The dial: residue mod |disc| -> index of the unique class, when defined."""
    if not is_residue_dial(disc):
        raise ValueError(f"D = {disc} does not support a residue dial")
    out: Dict[int, int] = {}
    for i, (_, s) in enumerate(dial_table(disc).items()):
        for r in s:
            out[r] = i
    return out


def read_class(disc: int, n: int) -> Optional[int]:
    """O(1) class lookup for N coprime to disc, using one modular reduction."""
    return readout(disc).get(n % abs(disc))


if __name__ == "__main__":
    for d in (-20, -84, -23):
        print(f"D = {d:>4}  h = {len(reduced_forms(d)):>2}  "
              f"dial = {is_residue_dial(d)}")
    print("readout mod 20 :", readout(-20))
    print("class of 1189  :", read_class(-20, 1189), " class of 21 :", read_class(-20, 21))

