function TENSOR(d1, d2):
    m <- d1.modulus * d2.modulus
    for each index i of d1, each index j of d2:
        S[(i,j)] <- { a in Z/m : (a mod d1.modulus) in d1.S[i]
                                and (a mod d2.modulus) in d2.S[j] }
    assert the sets S[(i,j)] are pairwise disjoint   # inherited, never fails
    return dial with modulus m and residue sets S

function READ(dial, N):
    r <- N mod dial.modulus
    return the unique index with r in its residue set, or NONE

