"""Algorithm: tensoring residue dials (stacking discriminants)."""

from __future__ import annotations

from dataclasses import dataclass
from math import isqrt
from typing import Dict, List, Optional, Set, Tuple

Form = Tuple[int, int, int]


def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return abs(a)


def reduced_forms(disc: int) -> List[Form]:
    forms: List[Form] = []
    for a in range(1, isqrt(abs(disc) // 3) + 2):
        for b in range(-a, a + 1):
            num = b * b - disc
            if num % (4 * a):
                continue
            c = num // (4 * a)
            if c < a or ((abs(b) == a or a == c) and b < 0):
                continue
            if gcd(gcd(a, b), c) != 1:
                continue
            forms.append((a, b, c))
    return forms


def unit_value_set(form: Form, m: int) -> Set[int]:
    a, b, c = form
    units = {u for u in range(m) if gcd(u, m) == 1}
    return {(a * x * x + b * x * y + c * y * y) % m
            for x in range(m) for y in range(m)} & units


@dataclass(frozen=True)
class ResidueDial:
    """A residue dial: modulus m, and disjoint admissible-residue sets."""
    modulus: int
    labels: Tuple[str, ...]
    residue_sets: Tuple[frozenset, ...]

    def __post_init__(self) -> None:
        for i in range(len(self.residue_sets)):
            for j in range(i + 1, len(self.residue_sets)):
                if self.residue_sets[i] & self.residue_sets[j]:
                    raise ValueError("residue sets are not disjoint: not a dial")

    def read(self, n: int) -> Optional[str]:
        """Read the class label of N from N mod m alone."""
        r = n % self.modulus
        for label, s in zip(self.labels, self.residue_sets):
            if r in s:
                return label
        return None


def dial_of_discriminant(disc: int) -> ResidueDial:
    forms = reduced_forms(disc)
    m = abs(disc)
    labels = tuple(f"{a}x^2{b:+d}xy+{c}y^2" for a, b, c in forms)
    sets = tuple(frozenset(unit_value_set(f, m)) for f in forms)
    return ResidueDial(m, labels, sets)


def tensor(d1: ResidueDial, d2: ResidueDial) -> ResidueDial:
    """The product dial, of modulus m1*m2 and index set the product of indices.

    Soundness is inherited by reducing modulo each factor; disjointness holds
    because distinct joint indices differ in some coordinate, whose residue sets
    were already disjoint.  Complexity O(m1*m2*|I1|*|I2|).
    """
    m = d1.modulus * d2.modulus
    labels: List[str] = []
    sets: List[frozenset] = []
    for l1, s1 in zip(d1.labels, d1.residue_sets):
        for l2, s2 in zip(d2.labels, d2.residue_sets):
            joint = frozenset(a for a in range(m)
                              if a % d1.modulus in s1 and a % d2.modulus in s2)
            labels.append(f"({l1} | {l2})")
            sets.append(joint)
    return ResidueDial(m, tuple(labels), tuple(sets))


if __name__ == "__main__":
    d20 = dial_of_discriminant(-20)
    d84 = dial_of_discriminant(-84)
    stacked = tensor(d20, d84)
    print(f"stacked modulus  : {stacked.modulus}")
    print(f"stacked positions: {sum(1 for s in stacked.residue_sets if s)} nonempty "
          f"of {len(stacked.residue_sets)}")
    for n in (109 * 421, 23 * 107):
        print(f"N = {n:>6}   N mod 1680 = {n % 1680:>4}   joint class = {stacked.read(n)}")
    print("Both semiprimes -- one with two principal factors, one with two")
    print("non-principal factors -- receive the same joint reading.")
